<script setup>
import {computed,ref,onMounted,onBeforeUnmount} from 'vue'
import Icon from './Icon.vue'
const props=defineProps({role:{type:String,default:'Student'},online:{type:Boolean,default:true}}),emit=defineEmits(['navigate'])
const query=ref(''),expanded=ref(false),search=ref(null)
const items=computed(()=>{
 const student=props.role==='Student',admin=props.role==='Admin'
 const all=[
  {id:'classrooms',icon:'BookOpen',art:'classroom',title:student?'Your next chapter':'Create room for learning',description:student?'Open your classes, find lesson materials and keep moving forward.':'Bring your subjects, teachers and learners together in one classroom.',cta:student?'Open classrooms':'Manage classrooms'},
  ...(student?[
   {id:'study',icon:'Coffee',art:'study',title:'Find your focus',description:'A space to settle in. Set a timer, choose your scene and study at your pace.',cta:'Enter study room'},
   {id:'schedule',icon:'CalendarDays',art:'calendar',title:'Make time for progress',description:'Your live lessons and upcoming sessions, organised in one clear calendar.',cta:'View schedule'}
  ]:[
   {id:'payments',icon:'Receipt',art:'payment',title:'Every payment, in view',description:'Review bank slips, confirm class access and follow your fee collections.',cta:'Review payments'},
   {id:admin?'team':'liveclasses',icon:admin?'Users':'Video',art:admin?'people':'classroom',title:admin?'Great teaching, together':'Connect your classroom',description:admin?'Review teacher requests and build the team behind your institute.':'Bring your learners into live lessons and keep your teaching organised.',cta:admin?'Meet your team':'Open live classes'}
  ]),
  {id:'papers',icon:'ClipboardCheck',art:'paper',title:'Turn practice into progress',description:'Create or complete papers, review marks and see the next step clearly.',cta:'Open papers'},
  ...(!student?[{id:'programmes',icon:'GraduationCap',art:'classroom',title:'Build a learning journey',description:'Connect modules and teachers in one programme, with one course enrolment.',cta:'Explore programmes'},{id:'schedule',icon:'CalendarDays',art:'calendar',title:'Plan what comes next',description:'See your sessions and organise your teaching week in one place.',cta:'Open schedule'}]:[{id:'payments',icon:'Receipt',art:'payment',title:'Class fees made clear',description:'See upcoming fees, send a bank slip and download your payment receipts.',cta:'View class fees'}]),
  {id:'connections',icon:'Users',art:'people',title:'Find your people',description:'Discover teachers and institutes. Follow their profiles and stay connected.',cta:'Explore profiles'},
  {id:'news',icon:'Newspaper',art:'paper',title:'Stay in the loop',description:'Your learning community’s latest announcements and updates.',cta:'Keep me updated'},
  {id:'profile',icon:'IdCard',art:'people',title:'Make it yours',description:'Keep your profile, contact details and preferences up to date.',cta:'Edit profile'},
  ...(admin||student?[{id:'liveclasses',icon:'Video',art:'classroom',title:'Learning, in real time',description:'Join your live classroom and keep your upcoming lessons close.',cta:'Open live classes'}]:[]),
  ...(student?[{id:'lessons',icon:'ShoppingBag',art:'classroom',title:'Keep your curiosity going',description:'Discover recorded lessons and return to the topics you want to explore.',cta:'Explore lesson store'},{id:'purchases',icon:'Receipt',art:'payment',title:'Your lessons, ready for you',description:'Return to your purchased learning content whenever you need it.',cta:'My purchases'}]:[{id:'library',icon:'Clapperboard',art:'classroom',title:'A home for your lessons',description:'Organise recordings and make your teaching available beyond the live class.',cta:'Open lecture library'}]),
  ...(admin?[{id:'storage',icon:'HardDrive',art:'paper',title:'Room for what matters',description:'See how much storage your teaching materials and recordings use.',cta:'View storage usage'},{id:'people',icon:'Users',art:'people',title:'Your learning community',description:'Find the people in your institute and keep your community connected.',cta:'Open community'}]:[]),
  {id:'hub',icon:'NotebookPen',art:'paper',title:'More ways to grow',description:'Find your learning tools, assessment resources and classroom activities.',cta:'Learning & teaching'},
  {id:'settings',icon:'Settings2',art:'calendar',title:'The way you like it',description:'Manage your account preferences and notification settings.',cta:'Open settings'},
  ...(!student?[{id:'subscription',icon:'CreditCard',art:'payment',title:'A plan that grows with you',description:'See your package, monthly enrolment breakdown and provider invoices.',cta:'Plans & billing'},{id:'operations',icon:'ListChecks',art:'calendar',title:'The details, taken care of',description:'Keep attendance records and support conversations close at hand.',cta:'Open attendance & support'}]:[])
 ]
 return all.filter(i=>props.online||!['study','news','liveclasses','library','lessons','purchases'].includes(i.id))
})
const shown=computed(()=>query.value?items.value.filter(i=>(i.title+' '+i.description+' '+i.cta).toLowerCase().includes(query.value.toLowerCase())):expanded.value?items.value:items.value.slice(0,3))
function shortcut(e){if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)){e.preventDefault();search.value?.focus()}}
onMounted(()=>window.addEventListener('keydown',shortcut));onBeforeUnmount(()=>window.removeEventListener('keydown',shortcut))
</script>
<template><section class="feature-gallery" aria-label="Explore your SISU workspace">
 <header class="feature-intro"><span class="feature-kicker"><Icon name="Sparkles" :size="14"/> YOUR SISU WORKSPACE</span><h1>{{role==='Student'?'A little curiosity. Endless possibilities.':'Great learning starts with you.'}}</h1><p>{{role==='Student'?'Everything you need for your next step, all in one place.':'Less time managing. More time making a difference.'}}</p></header>
 <div class="feature-search-frame"><label class="feature-search"><Icon name="Search" :size="20"/><input ref="search" v-model="query" type="search" placeholder="What would you like to do?" aria-label="Search workspace features"><kbd aria-hidden="true">Ctrl K</kbd></label></div>
 <div class="feature-gallery-heading"><h2>{{query?'Search results':'Your workspace, at a glance'}}</h2><button v-if="!query" class="text-button" @click="expanded=!expanded" :aria-expanded="expanded">{{expanded?'Show essentials':'Explore all features'}} <Icon :name="expanded?'ChevronUp':'ArrowRight'" :size="16"/></button><button v-else class="text-button" @click="query=''">Clear search</button></div>
