  <div class="feature-art" aria-hidden="true">
   <div class="art-outline outline-one"></div><div class="art-outline outline-two"></div>
   <div v-if="item.art==='calendar'" class="art-object art-calendar"><div class="art-window-bar"><i></i><i></i><i></i></div><div class="calendar-squares"><span v-for="n in 14" :class="{marked:[4,8,11].includes(n)}">{{n}}</span></div><span class="art-float-check"><Icon name="Check" :size="20"/></span></div>
   <div v-else-if="item.art==='people'" class="art-object art-people"><div v-for="n in 3" class="person-row"><span class="person-avatar"><Icon name="UserRound" :size="21"/></span><span class="person-lines"><i></i><i></i></span><span class="person-tick"><Icon name="Check" :size="14"/></span></div></div>
   <div v-else-if="item.art==='payment'" class="art-object art-payment"><div class="receipt-lines"><span class="art-mini-label">CLASS PAYMENT</span><b>LKR 8,000</b><i></i><i></i><span class="receipt-foot"><Icon name="Check" :size="14"/> Verified</span></div><span class="art-float-check"><Icon name="Check" :size="20"/></span></div>
   <div v-else-if="item.art==='study'" class="art-object art-study"><span class="timer-orbit"></span><Icon name="Coffee" :size="32"/><b>25:00</b><span class="timer-dot"></span></div>
   <div v-else-if="item.art==='paper'" class="art-object art-paper"><span class="art-mini-label">ONE STEP FORWARD</span><div v-for="n in 3" class="paper-answer"><span><Icon v-if="n===2" name="Check" :size="13"/></span><i></i></div><span class="art-float-check"><Icon name="Pencil" :size="19"/></span></div>
   <div v-else class="art-object art-classroom"><div class="art-window-bar"><i></i><i></i><i></i><span>YOUR CLASSROOM</span></div><div class="class-board"><Icon :name="item.icon" :size="31"/><div><i></i><i></i></div></div><div class="class-people"><span></span><span></span><span></span><i></i></div><span class="art-float-check"><Icon name="ArrowUpRight" :size="20"/></span></div>
  </div>
  <div class="feature-copy"><h3>{{item.title}}</h3><p>{{item.description}}</p><button class="feature-action" @click="emit('navigate',item.id)">{{item.cta}}<Icon name="ArrowUpRight" :size="16"/></button></div>
 </article></div><p v-if="!shown.length" class="feature-empty">No features match “{{query}}”. Try classes, payments, papers or profile.</p>
 </section></template>
<style scoped>
