transition:transform .5s;box-shadow:0 3px 10px #4c1d8015}.art-people{background:none;border:0;box-shadow:none;width:218px;display:grid;gap:9px}.person-row{display:flex;align-items:center;gap:11px;border:1px solid #dedee5;background:var(--feature-surface);border-radius:30px;padding:9px 12px;transition:transform .5s}.person-row:first-child{transform:translateX(7px);opacity:.55;border-style:dashed}.person-row:last-child{transform:translateX(-7px)}.person-avatar{display:grid;place-items:center;background:#f0e9f8;width:31px;height:31px;border-radius:50%}.person-lines{flex:1}.person-tick{border:1px solid #dfd1eb;border-radius:50%;height:21px;width:21px;display:grid;place-items:center}.art-payment{width:152px;transform:rotate(-5deg);border-radius:10px 10px 3px 3px}.receipt-lines{padding:17px 18px}.art-mini-label{font-size:7px;letter-spacing:.09em;color:#8b8491}.receipt-lines b{font-size:20px;display:block;letter-spacing:-.04em;margin:9px 0 12px;color:#28242e}.receipt-lines>i{height:4px;margin:8px 0}.receipt-lines>i:nth-of-type(2){width:67%}.receipt-foot{border-top:1px dashed #dedee5;padding-top:10px;margin-top:11px;display:flex;align-items:center;gap:5px;font-size:9px}.art-payment .art-float-check{right:-28px;bottom:26px}.art-calendar{width:180px}.calendar-squares{display:grid;grid-template-columns:repeat(7,1fr);padding:17px 12px;gap:7px}.calendar-squares>span{font-size:10px;width:16px;height:22px;display:grid;place-items:center;color:#919098}.calendar-squares .marked{background:#efe7f7;border-radius:5px;color:var(--feature-purple)}.calendar-squares .marked:nth-child(8){background:var(--feature-purple);color:#fff}.art-study{border-radius:50%;height:130px;width:130px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px}.art-study b{font-size:25px;font-weight:500;letter-spacing:-.04em;color:#2a2234}.timer-orbit{position:absolute;inset:-13px;border:1px dashed #dcd4e6;border-radius:50%}.timer-dot{position:absolute;top:4px;right:0;width:13px;height:13px;background:var(--feature-purple);border:3px solid #fff;border-radius:50%;transition:transform .5s}.art-paper{padding:18px;width:160px;transform:rotate(4deg)}.paper-answer{display:flex;align-items:center;gap:8px;margin-top:15px}.paper-answer>span{width:15px;height:15px;border:1px solid #d9d1e4;border-radius:4px;display:grid;place-items:center}.paper-answer>i{flex:1;height:4px}.feature-copy{padding:20px 12px 12px;display:flex;flex-direction:column;align-items:flex-start;flex:1}.feature-copy h3{font:600 17px/1.4 Inter,"Segoe UI",Arial,sans-serif;letter-spacing:-.02em;margin:0 0 10px;color:var(--feature-ink)}.feature-copy p{font-size:14px;line-height:1.6;margin:0 0 24px;color:var(--feature-muted);flex:1}.feature-action{border:1px solid #ded9e5;box-shadow:0 1px 2px #00000005;border-radius:8px;padding:10px 12px;display:flex;align-items:center;gap:15px;background:var(--feature-surface);color:var(--feature-ink);font:500 12px/1.3 Inter,"Segoe UI",Arial,sans-serif;cursor:pointer;min-height:40px}.feature-action svg{color:var(--feature-purple);transition:transform .25s}.feature-action:focus-visible{outline:2px solid var(--feature-purple);outline-offset:4px}.feature-empty{padding:28px;border:1px dashed #dedee5;border-radius:12px;text-align:center}
@media(hover:hover){.feature-card:hover{border-color:#c7b8da;box-shadow:0 4px 20px #37105209}.feature-card:hover .art-object{transform:translateY(-6px) rotate(-2deg)}.feature-card:hover .outline-one{transform:translate(8px,-8px)}.feature-card:hover .outline-two{transform:translate(-12px,10px)}.feature-card:hover .art-float-check{transform:translate(4px,-8px) rotate(10deg)}.feature-card:hover .person-row:first-child{transform:translateX(-5px)}.feature-card:hover .person-row:last-child{transform:translateX(5px)}.feature-card:hover .timer-dot{transform:translate(6px,14px)}.feature-action:hover{border-color:var(--feature-purple);color:var(--feature-purple);background:#faf7fd}.feature-action:hover svg{transform:translate(2px,-2px)}}
.feature-card:focus-within .art-object{transform:translateY(-5px)}
@media(max-width:1100px){.feature-grid{gap:14px}.feature-copy{padding:17px 8px 10px}.feature-copy h3{font-size:16px}.feature-art{height:165px}.art-object{scale:.9}}
@media(max-width:900px){.feature-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.feature-card:first-child{grid-column:1/-1}.feature-card:first-child{display:grid;grid-template-columns:1fr 1fr}.feature-card:first-child .feature-art{height:100%;min-height:190px}.feature-intro{padding-top:12px}}
@media(max-width:580px){.feature-grid{grid-template-columns:1fr}.feature-card:first-child{display:flex}.feature-art,.feature-card:first-child .feature-art{height:170px;min-height:170px}.feature-intro{text-align:left;padding:10px 0 22px}.feature-intro h1{font-size:28px}.feature-intro p{font-size:14px}.feature-search{padding:13px 12px}.feature-search kbd{display:none}.feature-gallery-heading h2{font-size:13px}.feature-gallery-heading button{font-size:11px}.feature-copy{padding:18px 12px 12px}.feature-gallery{margin-bottom:26px}.feature-action{min-height:44px}}
